const fetch = require('node-fetch');
const fs = require('fs');

async function mintNFT() {
  const url = 'https://staging.crossmint.com/api/2022-06-09/collections/default/nfts';

  const options = {
    method: 'POST',
    headers: {
      'x-api-key': 'sk_test_12345',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      recipient: 'email:user@example.com:polygon-amoy',
      metadata: {
        name: 'My NFT',
        description: 'Test NFT',
        image: 'https://example.com/image.png'
      }
    })
  };

  try {
    const response = await fetch(url, options);
    const data = await response.json();
    fs.writeFileSync('/home/user/fixed_mint_response.json', JSON.stringify(data, null, 2));
  } catch (error) {
    fs.writeFileSync('/home/user/fixed_mint_response.json', JSON.stringify({ error: error.message }, null, 2));
  }
}

mintNFT();

